create extension if not exists pgcrypto with schema extensions;  create table public.profiles (   id uuid primary key references auth.users(id) on delete cascade,   email text not null,   display_name text,   avatar_url text,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() );  create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin   insert into public.profiles (id, email, display_name, avatar_url)   values (     new.id,     coalesce(new.email, ''),     coalesce(nullif(new.raw_user_meta_data ->> 'display_name', ''), nullif(new.raw_user_meta_data ->> 'full_name', ''), nullif(new.raw_user_meta_data ->> 'name', '')),     nullif(new.raw_user_meta_data ->> 'avatar_url', '')   ) on conflict (id) do update set email = excluded.email;   return new; end; $$;  create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();  create table public.admin_users (   user_id uuid primary key references auth.users(id) on delete cascade,   created_at timestamptz not null default now() );  create table public.store_settings (   id text primary key default 'default' check (id = 'default'),   store_name text not null default 'JOE''s Store',   description text not null default 'Instant game credits, currency, and digital top-ups built for gamers.',   support_email text not null default 'support@example.com',   hero_badge text not null default 'THE NEXT LEVEL STARTS HERE',   hero_title text not null default 'Power up',   hero_highlight text not null default 'your game.',   hero_description text not null default 'Instant game credits, currency, and digital top-ups built for gamers who play to win.',   hero_image text not null default 'photo-1542751371-adc38448a05e',   updated_at timestamptz not null default now() );  create table public.categories (   id uuid primary key default gen_random_uuid(),   name text not null check (char_length(name) between 2 and 80),   slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),   description text not null default '',   image_url text,   icon text,   sort_order integer not null default 0,   is_active boolean not null default true,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() );  create table public.games (   id uuid primary key default gen_random_uuid(),   category_id uuid references public.categories(id) on delete set null,   name text not null,   slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),   description text not null default '',   logo_url text,   cover_url text,   platform text not null default 'PC',   is_featured boolean not null default false,   is_active boolean not null default true,   sort_order integer not null default 0,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() );  create table public.products (   id uuid primary key default gen_random_uuid(),   game_id uuid not null references public.games(id) on delete restrict,   category_id uuid references public.categories(id) on delete set null,   name text not null,   slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),   description text not null default '',   currency_amount text not null,   price numeric(10,2) not null check (price > 0),   compare_at_price numeric(10,2) check (compare_at_price is null or compare_at_price > price),   image_url text,   region text not null default 'Global',   platform text not null default 'All platforms',   is_active boolean not null default true,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now() );  create table public.offers (   id uuid primary key default gen_random_uuid(),   title text not null check (char_length(title) between 2 and 120),   description text not null default '',   image_url text,   discount_type text not null check (discount_type in ('percentage', 'fixed')),   discount_value numeric(10,2) not null check (discount_value > 0),   product_id uuid references public.products(id) on delete set null,   game_id uuid references public.games(id) on delete set null,   category_id uuid references public.categories(id) on delete set null,   starts_at timestamptz not null,   ends_at timestamptz not null,   is_active boolean not null default true,   sort_order integer not null default 0,   created_at timestamptz not null default now(),   updated_at timestamptz not null default now(),   constraint offers_valid_schedule check (ends_at > starts_at),   constraint offers_valid_discount check (discount_type <> 'percentage' or discount_value <= 100),   constraint offers_target_required check (product_id is not null or game_id is not null or category_id is not null) );  create index categories_active_order_idx on public.categories (sort_order, name) where is_active; create index games_active_order_idx on public.games (sort_order, name) where is_active; create index games_category_idx on public.games (category_id) where is_active; create index products_active_game_idx on public.products (game_id, created_at desc) where is_active; create index products_category_idx on public.products (category_id) where is_active; create index offers_schedule_idx on public.offers (starts_at, ends_at, sort_order) where is_active; create index offers_product_idx on public.offers (product_id) where is_active; create index offers_game_idx on public.offers (game_id) where is_active; create index offers_category_idx on public.offers (category_id) where is_active;  create view public.active_offers with (security_invoker = true) as select * from public.offers where is_active and starts_at <= now() and ends_at >= now();  create table public.audit_logs (   id uuid primary key default gen_random_uuid(),   admin_user_id uuid not null references public.admin_users(user_id) on delete restrict,   action text not null,   entity_type text not null,   entity_id uuid,   metadata jsonb not null default '{}'::jsonb,   created_at timestamptz not null default now() );  create table public.orders (   id uuid primary key default gen_random_uuid(),   user_id uuid not null references auth.users(id) on delete restrict,   email text not null,   status text not null default 'PENDING' check (status in ('PENDING','PAID','PROCESSING','COMPLETED','CANCELLED','REFUNDED')),   subtotal numeric(10,2) not null check (subtotal >= 0),   discount numeric(10,2) not null default 0 check (discount >= 0),   total numeric(10,2) not null check (total >= 0),   currency text not null default 'USD',   created_at timestamptz not null default now() );  create table public.coupons (   id uuid primary key default gen_random_uuid(),   code text not null unique,   discount_type text not null check (discount_type in ('percentage','fixed')),   discount_value numeric(10,2) not null check (discount_value > 0),   minimum numeric(10,2) check (minimum is null or minimum > 0),   max_discount numeric(10,2) check (max_discount is null or max_discount > 0),   expires_at timestamptz,   usage_limit integer check (usage_limit is null or usage_limit > 0),   uses integer not null default 0 check (uses >= 0),   is_active boolean not null default true,   created_at timestamptz not null default now() );  create table public.testimonials (   id uuid primary key default gen_random_uuid(),   name text not null,   role text not null,   quote text not null,   rating integer not null default 5 check (rating between 1 and 5),   is_active boolean not null default true,   created_at timestamptz not null default now() );  create table public.order_items (   id uuid primary key default gen_random_uuid(),   order_id uuid not null references public.orders(id) on delete cascade,   product_id uuid not null references public.products(id) on delete restrict,   product_name text not null,   quantity integer not null check (quantity between 1 and 50),   unit_price numeric(10,2) not null check (unit_price >= 0),   offer_id uuid references public.offers(id) on delete set null );  create index orders_user_date_idx on public.orders (user_id, created_at desc); create index order_items_order_idx on public.order_items (order_id);  grant select on public.orders, public.order_items to authenticated; create policy "users read own orders" on public.orders for select to authenticated using ((select auth.uid()) = user_id); create policy "admins read all orders" on public.orders for select to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "server checkout creates orders" on public.orders for insert with check (current_user = 'prisma'); create policy "server checkout reads new order id" on public.orders for select using (current_user = 'prisma'); create policy "users read own order items" on public.order_items for select to authenticated using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = (select auth.uid()))); create policy "admins read all order items" on public.order_items for select to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "server checkout creates order items" on public.order_items for insert with check (current_user = 'prisma'); create policy "server checkout reads active products" on public.products for select using (current_user = 'prisma'); create policy "server checkout reads active offers" on public.offers for select using (current_user = 'prisma'); create policy "users create own orders" on public.orders for insert to authenticated with check ((select auth.uid()) = user_id); create policy "users create order items" on public.order_items for insert to authenticated with check (exists (select 1 from public.orders o where o.id = order_id and o.user_id = (select auth.uid()))); alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.coupons enable row level security; alter table public.testimonials enable row level security;   create function public.set_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin   new.updated_at = now();   return new; end; $$;  create trigger profiles_set_updated_at before update on public.profiles for each row execute function public.set_updated_at(); create trigger categories_set_updated_at before update on public.categories for each row execute function public.set_updated_at(); create trigger games_set_updated_at before update on public.games for each row execute function public.set_updated_at(); create trigger products_set_updated_at before update on public.products for each row execute function public.set_updated_at(); create trigger offers_set_updated_at before update on public.offers for each row execute function public.set_updated_at(); create trigger settings_set_updated_at before update on public.store_settings for each row execute function public.set_updated_at();  alter table public.profiles enable row level security; alter table public.admin_users enable row level security; alter table public.store_settings enable row level security; alter table public.categories enable row level security; alter table public.games enable row level security; alter table public.products enable row level security; alter table public.offers enable row level security; alter table public.audit_logs enable row level security;  grant select on public.profiles to authenticated; grant update (display_name, avatar_url) on public.profiles to authenticated; grant select on public.admin_users to anon, authenticated; grant select on public.store_settings to anon, authenticated; grant insert, update on public.store_settings to authenticated; grant select on public.categories, public.games, public.products, public.offers to anon, authenticated; grant select on public.active_offers to anon, authenticated; grant insert, update, delete on public.categories, public.games, public.products, public.offers to authenticated; grant select on public.audit_logs to authenticated; grant insert on public.audit_logs to authenticated; grant select on public.coupons, public.testimonials to anon, authenticated; grant insert, update, delete on public.coupons, public.testimonials to authenticated;  create policy "profiles read self" on public.profiles for select to authenticated using ((select auth.uid()) = id); create policy "admins read profiles" on public.profiles for select to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "profiles update self" on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id); create policy "admin users read self" on public.admin_users for select to authenticated using ((select auth.uid()) = user_id); create policy "store settings are public" on public.store_settings for select to anon, authenticated using (true); create policy "admins manage store settings" on public.store_settings for all to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))) with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));  create policy "active categories visible" on public.categories for select to anon, authenticated using (is_active or exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins manage categories" on public.categories for all to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))) with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "active games visible" on public.games for select to anon, authenticated using (is_active or exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins manage games" on public.games for all to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))) with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "active products visible" on public.products for select to anon, authenticated using (is_active or exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins manage products" on public.products for all to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))) with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "current offers visible" on public.offers for select to anon, authenticated using (   (is_active and starts_at <= now() and ends_at >= now())   or exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())) ); create policy "admins manage offers" on public.offers for all to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))) with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins read audit log" on public.audit_logs for select to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins write audit log" on public.audit_logs for insert to authenticated with check (admin_user_id = (select auth.uid()) and exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "active testimonials are public" on public.testimonials for select to anon, authenticated using (is_active or exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins manage testimonials" on public.testimonials for all to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))) with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins read coupons" on public.coupons for select to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins manage coupons" on public.coupons for all to authenticated using (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))) with check (exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('store-media', 'store-media', true, 5242880, array['image/png','image/jpeg','image/webp','image/avif']) on conflict (id) do nothing;  create policy "store media is public" on storage.objects for select to anon, authenticated using (bucket_id = 'store-media'); create policy "admins upload store media" on storage.objects for insert to authenticated with check (bucket_id = 'store-media' and exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins update store media" on storage.objects for update to authenticated using (bucket_id = 'store-media' and exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))) with check (bucket_id = 'store-media' and exists (select 1 from public.admin_users a where a.user_id = (select auth.uid()))); create policy "admins delete store media" on storage.objects for delete to authenticated using (bucket_id = 'store-media' and exists (select 1 from public.admin_users a where a.user_id = (select auth.uid())));